package com.mengzhihua.crm.sales.service;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.sales.entity.*;import com.mengzhihua.crm.sales.repository.*;import org.springframework.stereotype.Service;
@Service public class ContactService {private final ContactRepository repo;public ContactService(ContactRepository r){repo=r;}public PageResult<Contact> list(int p,int s,String k,Long aid){if(aid!=null)return DtoUtil.page(repo.findByAccountId(aid,DtoUtil.pageable(p,s)),x->(Contact)x);return DtoUtil.page(k==null||k.isEmpty()?repo.findAll(DtoUtil.pageable(p,s)):repo.findByNameContainingIgnoreCase(k,DtoUtil.pageable(p,s)),x->(Contact)x);}public Contact get(Long id){return repo.findById(id).orElseThrow(()->new BizException("联系人不存在"));}public Contact save(Contact x){return repo.save(x);}public void delete(Long id){repo.deleteById(id);}}
